<div class="d-flex justify-content-between align-items-center mb-3"><h4>Payroll</h4><form method="POST" action="<?php echo BASE_URL; ?>/payroll/generate" class="d-flex gap-2"><input type="hidden" name="_token" value="<?php echo htmlspecialchars($_SESSION['csrf_token'] ??= bin2hex(random_bytes(32))); ?>"><input type="number" name="month" min="1" max="12" value="<?php echo date('n'); ?>" class="form-control" style="width:90px"><input type="number" name="year" value="<?php echo date('Y'); ?>" class="form-control" style="width:110px"><button class="btn btn-primary">Generate</button></form></div>
<div class="card p-3"><table class="table mb-0"><thead><tr><th>Employee</th><th>Period</th><th>Basic</th><th>Net</th><th>Status</th><th></th></tr></thead><tbody><?php foreach ($payroll as $row): ?><tr><td><?php echo htmlspecialchars($row['first_name'].' '.$row['last_name']); ?></td><td><?php echo sprintf('%02d/%d', $row['month'], $row['year']); ?></td><td><?php echo number_format($row['basic_salary'], 2); ?></td><td><?php echo number_format($row['net_salary'], 2); ?></td><td><?php echo htmlspecialchars($row['status']); ?></td><td><?php if ($row['status'] !== 'Paid'): ?><form method="POST" action="<?php echo BASE_URL; ?>/payroll/paid/<?php echo $row['id']; ?>"><input type="hidden" name="_token" value="<?php echo htmlspecialchars($_SESSION['csrf_token'] ??= bin2hex(random_bytes(32))); ?>"><button class="btn btn-sm btn-outline-success">Mark paid</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div>
